// Revisa los eventos y hoteles de Comfandi, guarda lo que ya vio y avisa al celular cuando sale algo nuevo.
// Corre sola dos veces al día (Cada día) y también cuando Armoni abre Salidas Ema (Webhook).
const sd = $getWorkflowStaticData('global');
const http = (o) => this.helpers.httpRequest(o);
const AHORA = Date.now();
const FUENTES = [
  { url: 'https://comfandivirtual.com.co/167-eventos-y-actividades', grupo: 'eventos' },
  { url: 'https://comfandivirtual.com.co/1281-hoteles', grupo: 'hoteles' }
];
const NO_QUIERO = /reprogramaci|bienestar[ -]activo|bienestar productivo|vital fit|\b50\+|crea mente/i;   // pasadías y programas que no son para ustedes
// pasadías: solo los de Cali o para ir en carro propio (pasaporte de granja, parque…); los que salen de la ciudad o llevan bus/hotel no
const ES_PASADIA = /pasad[ií]a/i;
const PASADIA_CALI = /\ben cali\b|carro propio|veh[ií]culo propio|pasaporte/i;
const PASADIA_NO = /transporte|bus\b|buseta|hotel|alojamiento|noche|ruta\b/i;
const NO_ES_PLAN = /\/libreria\/|\b(libro|[áa]lbum|kit)\b/i;                         // libros, álbumes y kits de la tienda
const OTRA_CIUDAD = /palmira|tulu[aá]|cartago|buga|jamund[ií]|yumbo|sevilla|zarzal|roldanillo|caicedonia|florida|pradera|candelaria/i;   // eventos fuera de Cali (los hoteles sí pueden ser fuera)
const PARA_ADULTOS = /concierto(?!\s*(did[aá]ctic|teatral|infantil))|\bcine\b|pel[ií]cula|carrera|stand ?up|adultos|vino|cata\b|rumba|fiesta/i;
const MESES = { enero: 1, febrero: 2, marzo: 3, abril: 4, mayo: 5, junio: 6, julio: 7, agosto: 8, septiembre: 9, setiembre: 9, octubre: 10, noviembre: 11, diciembre: 12 };
const HOY = new Date(AHORA - 5 * 3600 * 1000).toISOString().slice(0, 10);   // hora de Colombia
// la fecha del evento casi siempre viene en el nombre: «… 18 octubre 2026 4pm»
function fechaDe(t) {
  const m = String(t).toLowerCase().match(/\b(\d{1,2})\s+(?:de\s+)?(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)(?:\s+(?:de\s+)?(\d{4}))?/);
  if (!m) return null;
  let y = m[3] ? +m[3] : +HOY.slice(0, 4);
  const iso = (yy) => yy + '-' + String(MESES[m[2]]).padStart(2, '0') + '-' + String(+m[1]).padStart(2, '0');
  if (!m[3] && iso(y) < HOY && HOY.slice(5, 7) >= '11' && MESES[m[2]] <= 2) y++;   // en diciembre, «15 enero» es del año que viene
  return iso(y);
}

let esWeb = false, forzar = false;
try { esWeb = !!$('Webhook').first(); } catch (e) {}
if (esWeb) {
  const q = $('Webhook').first().json.query || {};
  if (q.token !== 'mercado-7d41c2a9e05b') return [{ json: { ok: false } }];
  forzar = q.forzar === '1';   // para probar: lee Comfandi ahora mismo sin esperar las 6 horas
}

const limpia = (t) => String(t || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#0?39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, ' ').trim();
const absoluta = (u) => !u ? '' : u.startsWith('//') ? 'https:' + u : u.startsWith('/') ? 'https://comfandivirtual.com.co' + u : u;

// PrestaShop devuelve el listado en JSON cuando se le pide como lo hace su propia página
function deJSON(j) {
  const ps = (j && (j.products || (j.listing && j.listing.products))) || [];
  return ps.map(p => ({
    id: String(p.id_product || p.id || p.url),
    nombre: limpia(p.name),
    url: absoluta(p.url || p.link),
    img: absoluta((p.cover && ((p.cover.bySize && (p.cover.bySize.home_default || p.cover.bySize.medium_default)) || p.cover.medium || p.cover.large || {}).url) || ''),
    precio: limpia(p.price || ''),
    detalle: limpia(p.description_short || '').slice(0, 180)
  }));
}
// si no llega JSON, se lee el HTML de las tarjetas de producto
function deHTML(html) {
  const out = [];
  const partes = String(html || '').split(/<article\b/i).slice(1);
  for (const a of partes) {
    if (!/product-miniature|js-product|product_item|product-item/i.test(a.slice(0, 400))) continue;
    const id = (a.match(/data-id-product="(\d+)"/) || [])[1];
    const url = (a.match(/href="(https?:\/\/[^"]+?\.html[^"]*)"/i) || [])[1] || '';
    let nombre = (a.match(/class="[^"]*product-title[^"]*"[^>]*>([\s\S]*?)<\/(?:h\d|div|p)>/i) || [])[1] || (a.match(/\balt="([^"]+)"/i) || [])[1] || '';
    const img = (a.match(/data-full-size-image-url="([^"]+)"/i) || a.match(/data-src="([^"]+)"/i) || a.match(/<img[^>]+src="([^"]+)"/i) || [])[1] || '';
    const precio = (a.match(/class="[^"]*\bprice\b[^"]*"[^>]*>([\s\S]*?)<\/span>/i) || [])[1] || '';
    nombre = limpia(nombre);
    if (!nombre || !url) continue;
    out.push({ id: id || url, nombre, url, img: absoluta(img), precio: limpia(precio), detalle: '' });
  }
  return out;
}

async function leerFuente(f) {
  const todos = [];
  for (let pag = 1; pag <= 4; pag++) {
    const u = f.url + (f.url.includes('?') ? '&' : '?') + 'page=' + pag;
    let lote = [], total = 1;
    try {
      const r = await http({ url: u + '&from-xhr', headers: { 'Accept': 'application/json, text/javascript, */*; q=0.01', 'X-Requested-With': 'XMLHttpRequest', 'User-Agent': 'Mozilla/5.0 (Armoni)' }, json: true, timeout: 20000 });
      const j = typeof r === 'string' ? JSON.parse(r) : r;
      lote = deJSON(j);
      total = (j && j.pagination && j.pagination.pages_count) || 1;
    } catch (e) {}
    if (!lote.length) {
      const html = await http({ url: u, headers: { 'User-Agent': 'Mozilla/5.0 (Armoni)', 'Accept': 'text/html' }, timeout: 20000 });
      lote = deHTML(html);
      const m = String(html).match(/[?&]page=(\d+)[^"]*"[^>]*>\s*(\d+)\s*</g);
      total = m ? Math.max(1, ...m.map(x => +((x.match(/>\s*(\d+)/) || [])[1] || 1))) : 1;
    }
    lote.forEach(p => { if (!todos.find(x => x.id === p.id)) todos.push(p); });
    if (pag >= total || !lote.length) break;
  }
  return todos.map(p => ({ ...p, grupo: f.grupo, dePasadias: !!f.pasadias }));
}

const hace = (h) => AHORA - h * 3600 * 1000;
const FILTRO = 3;   // al cambiar los filtros (ej. ahora entran los pasadías) se vuelve a leer Comfandi sin esperar las 6 horas
const fresco = !forzar && sd.revisado && sd.revisado > hace(6) && sd.version === 2 && sd.filtro === FILTRO;
let errores = [];
if (!esWeb || !fresco || !sd.planes) {
  const encontrados = [];
  // los pasadías viven en su propia categoría (Turismo › Pasadías): se busca el enlace en la página principal y, si no aparece, se usa el buscador de la tienda
  const fuentes = FUENTES.slice();
  try {
    if (!sd.urlPasadias || sd.urlPasadiasT < hace(24 * 7)) {
      const home = await http({ url: 'https://comfandivirtual.com.co/', headers: { 'User-Agent': 'Mozilla/5.0 (Armoni)', 'Accept': 'text/html' }, timeout: 20000 });
      const m = String(home).match(/href="((?:https?:\/\/comfandivirtual\.com\.co)?\/?\d+-pasad[ií]as[^"?#]*)"/i);
      if (m) { sd.urlPasadias = absoluta(m[1].startsWith('http') || m[1].startsWith('/') ? m[1] : '/' + m[1]); sd.urlPasadiasT = AHORA; }
    }
  } catch (e) {}
  if (!sd.urlPasadias) sd.urlPasadias = 'https://comfandivirtual.com.co/156-pasadias';   // la categoría Pasadías (comprobada)
  if (sd.urlPasadias) fuentes.push({ url: sd.urlPasadias, grupo: 'eventos', pasadias: true });
  fuentes.push({ url: 'https://comfandivirtual.com.co/buscar?controller=search&s=pasad%C3%ADa', grupo: 'eventos' });
  sd.fuentesInfo = [];
  for (const f of fuentes) {
    try { const l = await leerFuente(f); encontrados.push(...l); sd.fuentesInfo.push({ url: f.url, leidos: l.length, pasadias: l.filter(p => /pasad[ií]a/i.test(p.nombre)).length }); }
    catch (e) { errores.push(f.grupo + ': ' + (e.message || 'no se pudo leer')); sd.fuentesInfo.push({ url: f.url, error: String((e && e.message) || 'no se pudo leer').slice(0, 100) }); }
  }
  const vistosNombres = new Set();
  const sirven = encontrados.filter(p => {
    const t = p.nombre + ' ' + p.url;
    if (ES_PASADIA.test(t) || p.dePasadias) { if (!PASADIA_CALI.test(t) || PASADIA_NO.test(t) || OTRA_CIUDAD.test(t)) return false; p.tipo = 'pasadia'; }
    if (NO_QUIERO.test(t) || NO_ES_PLAN.test(t)) return false;
    if (p.grupo === 'eventos' && OTRA_CIUDAD.test(p.nombre + ' ' + p.detalle)) return false;
    p.fecha = fechaDe(p.nombre);
    if (p.fecha && p.fecha < HOY) return false;                          // ya pasó
    // la misma obra a las 2pm y a las 4pm: se muestra una sola vez
    const clave = p.nombre.toLowerCase().replace(/\b\d{1,2}(:\d{2})?\s*(am|pm)\b/g, '').replace(/\s+/g, ' ').trim();
    if (vistosNombres.has(clave)) return false;
    vistosNombres.add(clave);
    return true;
  });
  if (sirven.length || !errores.length) {
    const vistos = sd.vistos || {};
    // la primera revisión (o cuando cambian los filtros) solo aprende lo que ya hay: nada sale como «nuevo»
    const primeraVez = !sd.revisado || sd.version !== 2;
    if (primeraVez) { sd.version = 2; for (const k of Object.keys(vistos)) delete vistos[k]; }
    // «firma» de cada plan: si Comfandi le cambia el nombre, la fecha o el precio, cuenta como actualizado
    const firmas = sd.firmas || {}, actualizados = sd.actualizados || {};
    const nuevos = [];
    for (const p of sirven) {
      const firma = [p.nombre, p.precio, p.fecha || ''].join('|');
      if (!vistos[p.id]) { vistos[p.id] = primeraVez ? 1 : AHORA; if (!primeraVez) nuevos.push(p); }
      else if (!primeraVez && firmas[p.id] && firmas[p.id] !== firma) { vistos[p.id] = AHORA; actualizados[p.id] = AHORA; p.actualizado = true; nuevos.push(p); }
      firmas[p.id] = firma;
      if (actualizados[p.id] && actualizados[p.id] > hace(24 * 10)) p.actualizado = true;
      p.desde = vistos[p.id];
      // en eventos casi todo sirve para ir con Ema (Lego, inflables, teatro, zoológico…); lo de adultos va para ustedes dos
      p.paraEma = p.tipo === 'pasadia' || p.grupo === 'eventos' && !PARA_ADULTOS.test(p.nombre + ' ' + (p.description_short || '')) && !/\bcin[eé]\b|cinemark|cin[eé]polis|cine ?colombia|pel[ií]cula/i.test(p.nombre + ' ' + (p.description_short || ''));
    }
    // olvida lo que ya no está publicado desde hace más de 60 días
    const ids = new Set(sirven.map(p => p.id));
    for (const k of Object.keys(vistos)) if (!ids.has(k) && vistos[k] > 1 && vistos[k] < hace(24 * 60)) delete vistos[k];
    for (const k of Object.keys(firmas)) if (!ids.has(k) && !vistos[k]) delete firmas[k];
    for (const k of Object.keys(actualizados)) if (actualizados[k] < hace(24 * 30)) delete actualizados[k];
    sd.vistos = vistos; sd.firmas = firmas; sd.actualizados = actualizados; sd.planes = sirven; sd.revisado = AHORA; sd.filtro = FILTRO;

    // lo nuevo queda en la lista de «por avisar»; el aviso sale más abajo y, si falla, se reintenta en la próxima revisión (no se pierde)
    sd.sinAvisar = sd.sinAvisar || [];
    for (const p of nuevos) if (!sd.sinAvisar.find(x => x.id === p.id)) sd.sinAvisar.push({ id: p.id, nombre: p.nombre, precio: p.precio || '', grupo: p.grupo, paraEma: !!p.paraEma, tipo: p.tipo || '', actualizado: !!p.actualizado, t: AHORA });
  }
}

// aviso al celular: sale todo lo que esté «por avisar» (nuevos de ahora y los que fallaron antes); solo se borra de la lista cuando el envío salió bien
sd.sinAvisar = (sd.sinAvisar || []).filter(x => x.t > hace(24 * 3)).slice(-20);
if (sd.sinAvisar.length) {
  const nuevos = sd.sinAvisar, uno = nuevos[0];
  const titulo = nuevos.length === 1 ? (uno.actualizado ? '🔄 Comfandi actualizó un plan' : uno.tipo === 'pasadia' ? '🚗 Nuevo pasadía en Cali' : uno.grupo === 'hoteles' ? '🏨 Nuevo plan para ustedes' : (uno.paraEma ? '🎈 Nuevo plan para Ema' : '🎭 Nuevo en Comfandi')) : '✨ ' + nuevos.length + ' novedades en Comfandi';
  const cuerpo = nuevos.length === 1 ? uno.nombre + (uno.precio ? ' · ' + uno.precio : '') : nuevos.slice(0, 3).map(p => p.nombre).join(' · ');
  try {
    await http({ method: 'POST', url: 'http://localhost:5678/webhook/push-enviar', body: { token: 'mercado-7d41c2a9e05b', title: titulo, body: cuerpo, url: './?ver=ema', tag: 'comfandi' }, json: true, timeout: 15000 });
    sd.ultimoAviso = { t: AHORA, n: nuevos.length, ok: true, error: '' };
    sd.sinAvisar = [];
  } catch (e) {
    const msg = String((e && e.message) || 'no salió').slice(0, 120);
    errores.push('aviso: ' + msg);
    sd.ultimoAviso = { t: AHORA, n: nuevos.length, ok: false, error: msg };
  }
}
sd.errores = errores;
const planes = (sd.planes || []).slice().sort((a, b) => (b.desde || 0) - (a.desde || 0));
return [{ json: { web: esWeb, ok: true, revisado: sd.revisado ? new Date(sd.revisado).toISOString() : null, planes, errores, fuentes: sd.fuentesInfo || [], urlPasadias: sd.urlPasadias || null, porAvisar: (sd.sinAvisar || []).length, ultimoAviso: sd.ultimoAviso || null } }];
